// Done: matching a path against a pattern (do not change)
function matchPattern(pattern, path) {
  const ps = pattern.split("/").filter(Boolean), xs = path.split("/").filter(Boolean);
  const params = {};
  for (let i = 0; i < ps.length; i++) {
    if (ps[i] === "*") { params["*"] = xs.slice(i).join("/"); return params; }
    if (i >= xs.length) return null;
    if (ps[i][0] === ":") params[ps[i].slice(1)] = decodeURIComponent(xs[i]);
    else if (ps[i] !== xs[i]) return null;
  }
  return xs.length === ps.length ? params : null;
}
